def comps(g, color):
 seen=set(); out=[]
 for r in range(len(g)):
  for c in range(len(g[0])):
   if g[r][c]!=color or (r,c) in seen: continue
   st=[(r,c)]; seen.add((r,c)); cc=[]
   while st:
    x,y=st.pop(); cc.append((x,y))
    for a,b in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
     if 0<=a<len(g) and 0<=b<len(g[0]) and g[a][b]==color and (a,b) not in seen: seen.add((a,b));st.append((a,b))
   out.append(cc)
 return sorted(out,key=len,reverse=True)
